import math

def is_perfect_cube(n):
    if n == 0:
        return True

    # Handle negative numbers
    sign = 1
    if n < 0:
        sign = -1
        n = -n

    # Calculate the cube root
    cbrt = round(n**(1/3))

    # Check if it's a perfect cube
    return sign * (cbrt**3) == abs(n)

def calculate_P(x):
    return (8*x - 41) * (x + 3)**2

results = {}
for x in range(-10, 11):
    px = calculate_P(x)
    is_cube = is_perfect_cube(px)
    results[x] = (px, is_cube)

print("--- Results ---")
for x, (px, is_cube) in results.items():
    print(f"x={x}: P(x)={px}, Is Perfect Cube: {is_cube}")

perfect_cubes_found = {x: px for x, (px, is_cube) in results.items() if is_cube}
print("\n--- Perfect Cubes Found ---")
print(perfect_cubes_found)
